with filtered as (select id, customer_id, plan, start_date, end_date, status, add_months(end_date, 3) as end_date_plus_months from subscriptions where end_date > date '2023-07-30'), with_windows as (select *, row_number() over (order by end_date desc, id) as seq_no, row_number() over (order by end_date, id) as row_seq, row_number() over (partition by plan order by end_date desc, id) as event_seq from filtered), metrics as (select *, first_value(seq_no) ignore nulls over (partition by plan order by event_seq, id rows between unbounded preceding and current row) as first_known_seq_no, dense_rank() over (partition by plan order by row_seq desc) as row_seq_dense_rank, max(seq_no) over (partition by customer_id, status) as customer_id_max_seq_no, avg(event_seq) over (partition by plan, customer_id order by seq_no, id rows between 2 preceding and current row) as event_seq_avg_2 from with_windows), latest as (select *, row_number() over (partition by customer_id order by seq_no, id) as row_num from metrics qualify row_num = 1) select status, count(*) filter (where plan = 'basic') as basic_rows, count(case when plan = 'basic' then 1 end) as basic_count, sort_array(collect_set(status)) as status_list from latest group by status having count(case when plan = 'basic' then 1 end) > 1;
